  "definition": "TES = \\frac{\\sum_{i \\in treatmentbasics} (therapy\\_details_i['engagement\\_score'])} {|treatmentbasics|}, \\text{where } engagement\\_score = \\begin{cases} 3 & \\text{if } therapy\\_details['engagement'] = High \\\\ 2 & \\text{if } therapy\\_details['engagement'] = Medium \\\\ 1 & \\text{if } therapy\\_details['engagement'] = Low \\\\ 0 & \\text{if } therapy\\_details['engagement'] = Non-compliant \\end{cases}, \\text{and } therapy\\_details \\text{ is the JSONB column in the treatmentbasics table}"
