CREATE OR REPLACE FUNCTION calculate_tes(p_txkey integer)
RETURNS numeric AS $$
DECLARE
    v_engagement text;
    v_score numeric;
BEGIN
    -- Get the engagement value from therapy_details JSONB
    SELECT therapy_details->>'engagement' INTO v_engagement
    FROM treatmentbasics
    WHERE txkey = p_txkey;

    -- Map engagement to score
    CASE
        WHEN v_engagement = 'High' THEN v_score := 3
        WHEN v_engagement = 'Medium' THEN v_score := 2
        WHEN v_engagement = 'Low' THEN v_score := 1
        WHEN v_engagement = 'Non-compliant' THEN v_score := 0
        ELSE v_score := 0
    END;

    RETURN v_score;
END;
$$ LANGUAGE plpgsql;

